package com.qiusheng.leftmineext;

import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.thecallunxz.left2mine.combat.CarryableEntity;

import java.lang.reflect.Method;

/**
 * White outline: generated by a Left 2 Mine item spawn point (no player owner).
 * Orange outline: thrown/dropped by a player (owner is a Player).
 */
public final class QuestCanHighlighter {
    private static final org.slf4j.Logger LOGGER = com.mojang.logging.LogUtils.getLogger();
    private static final String WHITE_TEAM = "leftmineext_quest_white";
    private static final String ORANGE_TEAM = "leftmineext_quest_orange";

    public static void tick(MinecraftServer server) {
        for (ServerLevel level : server.getAllLevels()) {
            for (Entity entity : level.getAllEntities()) {
                if (!(entity instanceof CarryableEntity can)
                        || !can.item().is(LeftMineRegistry.QUEST_GASCAN.get())) {
                    continue;
                }
                can.setGlowingTag(true);
                applyTeam(level, can, can.getOwner() instanceof Player);
            }
        }
    }

    /**
     * The score/team classes are referenced reflectively because the current
     * compiler classpath has a malformed ChatFormatting annotation entry.
     */
    private static void applyTeam(ServerLevel level, CarryableEntity can, boolean orange) {
        try {
            Object scoreboard = level.getClass().getMethod("getScoreboard").invoke(level);
            Class<?> teamClass = Class.forName("net.minecraft.world.scores.PlayerTeam");
            Class<?> colorClass = Class.forName("net.minecraft.ChatFormatting");
            String name = orange ? ORANGE_TEAM : WHITE_TEAM;

            Method getTeam = scoreboard.getClass().getMethod("getPlayerTeam", String.class);
            Object team = getTeam.invoke(scoreboard, name);
            if (team == null) {
                Method addTeam = scoreboard.getClass().getMethod("addPlayerTeam", String.class);
                team = addTeam.invoke(scoreboard, name);
                Object color = Enum.valueOf(colorClass.asSubclass(Enum.class), orange ? "GOLD" : "WHITE");
                teamClass.getMethod("setColor", colorClass).invoke(team, color);
                teamClass.getMethod("setSeeFriendlyInvisibles", boolean.class).invoke(team, false);
            }
            Method addPlayer = scoreboard.getClass().getMethod("addPlayerToTeam", String.class, teamClass);
            addPlayer.invoke(scoreboard, can.getStringUUID(), team);
        } catch (Throwable e) {
            LOGGER.warn("[leftmineext] quest can team failed", e);
        }
    }

    private QuestCanHighlighter() {
    }
}
